#!/usr/bin/env python3
"""Run one command in its own process group with a hard wall-clock deadline."""

# Some portions generated by Codex

from __future__ import annotations

import argparse
import datetime as dt
import json
import os
import pathlib
import signal
import subprocess
import sys
import time


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--timeout-seconds", type=float, required=True)
    parser.add_argument("--termination-grace-seconds", type=float, default=5.0)
    parser.add_argument("--status", type=pathlib.Path, required=True)
    parser.add_argument("--stdout", type=pathlib.Path, required=True)
    parser.add_argument("--stderr", type=pathlib.Path, required=True)
    parser.add_argument("command", nargs=argparse.REMAINDER)
    args = parser.parse_args()
    if args.command and args.command[0] == "--":
        args.command = args.command[1:]
    if args.timeout_seconds <= 0 or args.termination_grace_seconds < 0 or not args.command:
        parser.error("positive timeout, non-negative grace, and a command are required")
    return args


def utc_now() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat()


def terminate_group(process: subprocess.Popen[bytes], grace_seconds: float) -> str:
    try:
        os.killpg(process.pid, signal.SIGTERM)
    except ProcessLookupError:
        return "already-exited"
    try:
        process.wait(timeout=grace_seconds)
        return "sigterm"
    except subprocess.TimeoutExpired:
        try:
            os.killpg(process.pid, signal.SIGKILL)
        except ProcessLookupError:
            return "sigterm"
        process.wait()
        return "sigkill"


def write_status(path: pathlib.Path, status: dict[str, object]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    temporary.write_text(json.dumps(status, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    temporary.replace(path)


def main() -> int:
    args = parse_args()
    args.stdout.parent.mkdir(parents=True, exist_ok=True)
    args.stderr.parent.mkdir(parents=True, exist_ok=True)
    started_at = utc_now()
    started = time.monotonic()
    timed_out = False
    termination = "none"
    with args.stdout.open("wb") as stdout, args.stderr.open("wb") as stderr:
        process = subprocess.Popen(
            args.command,
            stdin=subprocess.DEVNULL,
            stdout=stdout,
            stderr=stderr,
            start_new_session=True,
        )
        try:
            exit_code = process.wait(timeout=args.timeout_seconds)
        except subprocess.TimeoutExpired:
            timed_out = True
            termination = terminate_group(process, args.termination_grace_seconds)
            exit_code = process.returncode
    elapsed_seconds = time.monotonic() - started
    status = {
        "formatVersion": 1,
        "command": args.command,
        "startedAt": started_at,
        "finishedAt": utc_now(),
        "elapsedSeconds": elapsed_seconds,
        "timeoutSeconds": args.timeout_seconds,
        "timedOut": timed_out,
        "termination": termination,
        "exitCode": exit_code,
        "stdout": str(args.stdout.resolve()),
        "stderr": str(args.stderr.resolve()),
        "outcome": "timeout" if timed_out else "succeeded" if exit_code == 0 else "failed",
    }
    write_status(args.status, status)
    if timed_out:
        return 124
    return int(exit_code or 0)


if __name__ == "__main__":
    sys.exit(main())
